use vstd::prelude::*;
use vstd::slice::*;

verus! {

spec fn is_odd(x: i32) -> bool {
    x % 2 != 0
}

spec fn all_even_up_to(s: Seq<i32>, end: nat) -> bool 
    requires end <= s.len()
{
    forall|i: nat| i < end ==> !is_odd(s[i])
}

fn find_first_odd(a: &[i32]) -> (found: bool, index: usize)
    ensures
        // If not found, all elements are even
        !found ==> all_even_up_to(a@, a@.len()),
        // If found, index is valid and points to first odd
        found ==> (
            0 <= index < a@.len(),
            is_odd(a@[index as nat]),
            all_even_up_to(a@, index as nat)
        )
{
    let mut i: usize = 0;
    let len = a.len();
    
    while i < len
        invariant
            0 <= i <= len,
            // All elements before i are even
            all_even_up_to(a@, i as nat),
        decreases len - i,
    {
        if is_odd(a[i]) {
            // Found the first odd element
            return (true, i);
        }
        i = i + 1;
    }
    
    // No odd element found
    (false, 0)
}

}